const isMissing = (v) => {
  if (v === null || v === undefined) return true;
  const s = String(v).trim().toLowerCase();
  return s === '' || s === 'null';
};
const clean = (v) => (isMissing(v) ? '' : v);
const num = (v) =>
  isMissing(v) ? '' : Number(String(v).replace(/[^0-9.\-]/g, ''));

const fileName = $('Loop Over Items').first().json.fileName || 'Unknown document';

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.flags)) sd.flags = [];

const rows = [];

for (const item of $input.all()) {
  const po = item.json.data || {};
  const articles = Array.isArray(po.articles) ? po.articles : [];

  // --- per-document flagging ---
  const missingHeader = [];
  const headerChecks = {
    'Customer': po.customer,
    'Supplier': po.supplier,
    'LPO No': po.po_number,
    'Date': po.po_date,
  };
  for (const [label, val] of Object.entries(headerChecks)) {
    if (isMissing(val)) missingHeader.push(label);
  }

  const badArticles = [];
  if (articles.length === 0) {
    badArticles.push('no articles extracted');
  } else {
    articles.forEach((a, i) => {
      const miss = [];
      if (isMissing(a.article)) miss.push('name');
      if (isMissing(a.unit)) miss.push('unit');
      if (isMissing(a.quantity)) miss.push('qty');
      if (isMissing(a.rate)) miss.push('rate');
      if (miss.length) badArticles.push(`row ${i + 1} (${miss.join(', ')})`);
    });
  }

  if (missingHeader.length || badArticles.length) {
    sd.flags.push({ document: fileName, missingHeader, badArticles });
  }

  // --- build sheet rows ---
  articles.forEach((a, idx) => {
    const qty = num(a.quantity);
    const rate = num(a.rate);
    const total = (qty === '' || rate === '') ? '' : qty * rate;

    rows.push({
      json: {
        'Date': clean(po.po_date),
        'Customer': clean(po.customer),
        'Supplier': clean(po.supplier),
        'LPO No': idx === 0 ? clean(po.po_number) : '',
        'Delivery Date': clean(po.delivery_date),
        'Items': clean(a.article),
        'Unit': clean(a.unit),
        'Qty': qty,
        'Rate': rate,
        'Total': total,
        'Document Name': fileName,
      },
    });
  });
}

return rows;

const sd = $getWorkflowStaticData('global');

// Build the set of PO numbers already in the sheet
const seen = [];
for (const row of $input.all()) {
  const v = row.json ? row.json['LPO No'] : undefined;
  if (v !== null && v !== undefined && String(v).trim() !== '') {
    seen.push(String(v).trim());
  }
}
sd.seenPOs = seen;
sd.flags = [];
sd.duplicates = [];
sd.processedCount = 0;

// Split the uploaded PDFs (sourced from the form node)
const out = [];
for (const item of $('On form submission').all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    out.push({ json: { fileName: bin[key].fileName || key }, binary: { data: bin[key] } });
  }
}
return out;

const sd = $getWorkflowStaticData('global');
const flags = Array.isArray(sd.flags) ? sd.flags : [];
const dupes = Array.isArray(sd.duplicates) ? sd.duplicates : [];

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const clean = flags.length === 0;
const n = flags.length;

const total = typeof sd.processedCount === 'number' ? sd.processedCount : (flags.length + dupes.length);
const added = total - dupes.length;

let cards = '';
for (const f of flags) {
  const mh = Array.isArray(f.missingHeader) ? f.missingHeader : [];
  const ba = Array.isArray(f.badArticles) ? f.badArticles : [];
  let issues = '';
  if (mh.length) {
    issues += `<div class="eb-row"><span class="eb-lbl">Header fields</span><span class="eb-chips">` +
      mh.map(h => `<span class="eb-chip">${esc(h)}</span>`).join('') + `</span></div>`;
  }
  if (ba.length) {
    issues += `<div class="eb-row"><span class="eb-lbl">Article rows</span><span class="eb-chips">` +
      ba.map(a => `<span class="eb-chip">${esc(a)}</span>`).join('') + `</span></div>`;
  }
  cards += `<div class="eb-card"><div class="eb-doc">${esc(f.document)}</div>${issues}</div>`;
}

let dupSection = '';
if (dupes.length) {
  const rows = dupes.map(dp =>
    `<div class="eb-dup-row"><span class="eb-dup-doc">${esc(dp.document)}</span><span class="eb-dup-po">${esc(dp.po_number)}</span></div>`
  ).join('');
  dupSection = `<div class="eb-dupbox"><div class="eb-dup-title">Already processed &middot; skipped (${dupes.length})</div>${rows}</div>`;
}

const statusClass = clean ? 'eb-ok' : 'eb-warn';
const icon = clean ? '&#10003;' : '&#33;';

let sub;
if (!clean) {
  sub = `${n} document${n === 1 ? '' : 's'} below may have fields worth a quick check against the original PDF.`;
} else if (added === 0) {
  sub = 'No new data was added. The documents below were already processed.';
} else if (dupes.length) {
  sub = `${added} document${added === 1 ? '' : 's'} added. ${dupes.length} already processed and skipped (below).`;
} else {
  sub = 'All documents were extracted cleanly. No missing fields detected.';
}

const html = `
<style>
  #eb { font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; color: #1f2933; max-width: 620px; margin: 56px auto 0; padding: 40px 44px 32px; background: #fff; border: 1px solid #e6e9f0; border-radius: 16px; box-shadow: 0 12px 40px rgba(20,30,70,0.08); }
  #eb * { box-sizing: border-box; }
  #eb .eb-badge { width: 58px; height: 58px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 28px; font-weight: 700; margin: 4px auto 20px; }
  #eb .eb-ok { background: #e7f7ef; color: #1a9d63; }
  #eb .eb-warn { background: #fdf3e2; color: #d98617; }
  #eb h2 { text-align: center; font-size: 22px; font-weight: 600; margin: 0 0 8px; }
  #eb .eb-sub { text-align: center; color: #5b6472; font-size: 15px; line-height: 1.5; margin: 0 0 28px; }
  #eb .eb-cards { display: flex; flex-direction: column; gap: 14px; }
  #eb .eb-card { background: #fdf9f0; border: 1px solid #f4e4c6; border-radius: 12px; padding: 18px 20px; }
  #eb .eb-doc { font-weight: 600; font-size: 15px; margin-bottom: 10px; word-break: break-word; }
  #eb .eb-row { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 10px; }
  #eb .eb-lbl { font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; color: #8a94a6; min-width: 92px; padding-top: 4px; }
  #eb .eb-chips { display: flex; flex-wrap: wrap; gap: 7px; flex: 1; }
  #eb .eb-chip { background: #fff; color: #b8710f; border: 1px solid #f4dcae; border-radius: 999px; padding: 3px 11px; font-size: 13px; }
  #eb .eb-dupbox { margin-top: 16px; background: #f3f6fb; border: 1px solid #dce4f0; border-radius: 12px; padding: 16px 20px; }
  #eb .eb-dup-title { font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; color: #6b7688; margin-bottom: 10px; }
  #eb .eb-dup-row { display: flex; justify-content: space-between; gap: 12px; padding: 5px 0; border-top: 1px solid #e6ecf5; font-size: 14px; }
  #eb .eb-dup-row:first-of-type { border-top: none; }
  #eb .eb-dup-doc { color: #3b4453; word-break: break-word; }
  #eb .eb-dup-po { color: #8a94a6; white-space: nowrap; }
  #eb .eb-foot { text-align: center; color: #9aa3b2; font-size: 12px; margin-top: 30px; }
</style>
<div id="eb">
  <div class="eb-badge ${statusClass}">${icon}</div>
  <h2>Extraction complete</h2>
  <p class="eb-sub">${esc(sub)}</p>
  ${clean ? '' : `<div class="eb-cards">${cards}</div>`}
  ${dupSection}
  <div class="eb-foot">Powered by easybits Extractor</div>
</div>
`;

return [{ json: { html } }];

const isMissing = (v) => {
  if (v === null || v === undefined) return true;
  const s = String(v).trim().toLowerCase();
  return s === '' || s === 'null';
};
const clean = (v) => (isMissing(v) ? '' : v);
const num = (v) => isMissing(v) ? '' : Number(String(v).replace(/[^0-9.\-]/g, ''));

const DEFAULT_CURRENCY = 'AED';   // fallback when the PO doesn't state one
const DEFAULT_UOM      = 'EA';

const po = $input.first().json.data || {};
const articles = Array.isArray(po.articles) ? po.articles : [];

const lines = articles.map((a, i) => {
  const qty   = num(a.quantity);
  const price = num(a.rate);
  const total = (qty === '' || price === '') ? 0 : qty * price;
  return {
    line_number: i + 1,
    description: clean(a.article),
    item_code:   clean(a.article_no),
    quantity:    qty === '' ? 0 : qty,
    uom:         clean(a.unit) || DEFAULT_UOM,
    unit_price:  price === '' ? 0 : price,
    line_total:  total,
  };
});

return [{
  json: {
    po_number:     clean(po.po_number),
    po_date:       clean(po.po_date),
    delivery_date: clean(po.delivery_date),
    customer:      clean(po.customer),
    supplier:      clean(po.supplier),
    currency:      clean(po.currency) || DEFAULT_CURRENCY,
    lines,
  },
}];

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.seenPOs)) sd.seenPOs = [];
if (!Array.isArray(sd.duplicates)) sd.duplicates = [];
if (typeof sd.processedCount !== 'number') sd.processedCount = 0;
sd.processedCount += 1;

const item = $input.first();
const po = (item.json && item.json.data) ? item.json.data : {};
const raw = po.po_number;
const poNum = (raw === null || raw === undefined) ? '' : String(raw).trim();
const missing = poNum === '' || poNum.toLowerCase() === 'null';

const fileName = $('Loop Over Items').first().json.fileName || 'Unknown document';

let isDup = false;
if (!missing) {
  if (sd.seenPOs.includes(poNum)) {
    isDup = true;
    sd.duplicates.push({ document: fileName, po_number: poNum });
  } else {
    sd.seenPOs.push(poNum);
  }
}

item.json._duplicate = isDup;
return [item];
